Use ASP.NET Core's built-in `WebApplicationFactory<T>` from the `Microsoft.AspNetCore.Mvc.Testing` package. It spins up your entire middleware pipeline in-memory — no ports, no real server.

**1. Add the NuGet package to your test project:**
```
dotnet add package Microsoft.AspNetCore.Mvc.Testing
```

**2. Create a test class:**
```csharp
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class McpIntegrationTests
    : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsServerCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/list",
            @params = new { }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

**3. If you need to mock dependencies** (e.g., a database), override services:
```csharp
var factory = new WebApplicationFactory<Program>()
    .WithWebHostBuilder(builder =>
    {
        builder.ConfigureServices(services =>
        {
            services.AddSingleton<IMyService, FakeMyService>();
        });
    });
```

**Key points:**
- `Program` must be accessible — add `public partial class Program { }` to your server's `Program.cs` if using top-level statements.
- Adjust `"/mcp"` to match your actual MCP endpoint path.
- For **SSE transport**, use `factory.CreateDefaultClient()` and read the SSE stream with `HttpCompletionOption.ResponseHeadersRead`.
- The entire ASP.NET pipeline (routing, middleware, DI) runs exactly as in production — just without network I/O.
